const url = $input.first().json.body.url;
// Extract video ID from various YouTube URL formats
let videoId = null;
const patterns = [
  /(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/|youtube\.com\/v\/)([a-zA-Z0-9_-]{11})/,
  /^([a-zA-Z0-9_-]{11})$/
];
for (const pattern of patterns) {
  const match = url.match(pattern);
  if (match) {
    videoId = match[1];
    break;
  }
}
if (!videoId) {
  throw new Error('Invalid YouTube URL. Could not extract video ID.');
}
return { videoId, url };

// ============================================================
// Fetch Transcript with automatic fallback (v9)
// Primary:   youtubetranscript.com (free, keyless — same as paid)
// Fallback:  local bridge using youtube-transcript-api (optional)
// ============================================================
const videoId = $json.videoId;
// Optional secondary source. Leave empty to disable.
// Point at any transcript API you have (e.g. a local bridge or
// transcriptapi.com with your key). Primary source is free & keyless.
const FALLBACK_URL = '';

let raw = null;
let source = 'youtubetranscript.com';

// 1) Primary source (free, no API key)
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://youtubetranscript.com/?server_vid2=${videoId}`,
    responseFormat: 'text',
    timeout: 20000,
  });
  const isBlocked = /currently blocking us|working on a fix|can't fetch|unable to fetch/i.test(resp) && resp.length < 400;
  if (!isBlocked && resp.includes('<text')) {
    raw = resp;
  }
} catch (e) {
  // primary unavailable -> try fallback
}

// 2) Fallback source (local bridge / any configured transcript API)
if (!raw && FALLBACK_URL) {
  try {
    const fb = await this.helpers.httpRequest({
      method: 'GET',
      url: `${FALLBACK_URL}?video_id=${videoId}`,
      json: true,
      timeout: 30000,
    });
    if (fb && fb.ok && fb.transcript) {
      raw = fb.transcript;
      source = 'local-bridge';
    }
  } catch (e) {
    // fallback unavailable
  }
}

if (!raw) {
  throw new Error('Could not fetch a transcript for this video. The free transcript service is temporarily blocked by YouTube — try a video with captions, or try again later.');
}

// Parse: XML <text> tags (primary) or plain text (fallback)
let transcript = '';
const textMatches = raw.match(/<text[^>]*>([\s\S]*?)<\/text>/g) || [];
if (textMatches.length) {
  transcript = textMatches
    .map(t => t.replace(/<[^>]+>/g, '').trim())
    .filter(t => t.length > 0)
    .join(' ');
} else {
  transcript = raw
    .split('\n')
    .filter(l => l.trim() && !l.includes('[') && !l.includes('((') && l.length > 5)
    .join(' ');
}
transcript = transcript.trim();
if (!transcript) {
  throw new Error('Could not extract a transcript for this video. It may have no captions, or the transcript service is unavailable.');
}

return {
  transcript: transcript.substring(0, 25000),
  wordCount: transcript.split(' ').length,
  source,
};

// OpenAI node (simplifyOutput: true) returns { message: { role, content } }
// The model is instructed to return JSON with key "summary".
const msg = $input.first().json.message;
const content = (msg && msg.content) || '';
let summary = content.trim();
try {
  const parsed = JSON.parse(content);
  if (parsed && parsed.summary) {
    summary = parsed.summary;
  }
} catch (e) {
  // content was plain text
}

const prev = $('Fetch Transcript').first().json;
return {
  videoUrl: $('Extract Video ID').first().json.url || '',
  videoId: $('Extract Video ID').first().json.videoId || '',
  wordCount: prev.wordCount || 0,
  summary,
};
